CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', pickup_code text UNIQUE NOT NULL DEFAULT upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)), avatar_path text, original_user_id text UNIQUE);
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.clubs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, default_unit text NOT NULL DEFAULT 'lb' CHECK(default_unit IN ('lb','kg')), currency text NOT NULL DEFAULT '$' CHECK(currency IN ('$','£','€')), owner_id uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.clubs TO authenticated; GRANT ALL ON public.clubs TO service_role;
ALTER TABLE public.clubs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.club_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), club_id uuid NOT NULL REFERENCES public.clubs(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'customer' CHECK(role IN ('admin','stringer','customer')), approved boolean NOT NULL DEFAULT false, UNIQUE(club_id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.club_members TO authenticated; GRANT ALL ON public.club_members TO service_role;
ALTER TABLE public.club_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.racqr_staff(c uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM club_members WHERE club_id=c AND user_id=auth.uid() AND approved AND role IN ('admin','stringer')) $$;
CREATE FUNCTION public.racqr_admin(c uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM club_members WHERE club_id=c AND user_id=auth.uid() AND approved AND role='admin') $$;
CREATE FUNCTION public.racqr_member(c uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM club_members WHERE club_id=c AND user_id=auth.uid()) $$;
CREATE FUNCTION public.racqr_can_view_profile(p uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p=auth.uid() OR EXISTS(SELECT 1 FROM club_members m WHERE m.user_id=p AND racqr_staff(m.club_id)) $$;
REVOKE ALL ON FUNCTION public.racqr_staff(uuid),public.racqr_admin(uuid),public.racqr_member(uuid),public.racqr_can_view_profile(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.racqr_staff(uuid),public.racqr_admin(uuid),public.racqr_member(uuid),public.racqr_can_view_profile(uuid) TO authenticated;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(public.racqr_can_view_profile(id));
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE POLICY clubs_read ON public.clubs FOR SELECT TO authenticated USING(owner_id=auth.uid() OR public.racqr_member(id));
CREATE POLICY clubs_insert ON public.clubs FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid());
CREATE POLICY clubs_update ON public.clubs FOR UPDATE TO authenticated USING(public.racqr_admin(id)) WITH CHECK(public.racqr_admin(id));
CREATE POLICY members_read ON public.club_members FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.racqr_staff(club_id));
CREATE POLICY members_update ON public.club_members FOR UPDATE TO authenticated USING(public.racqr_admin(club_id)) WITH CHECK(public.racqr_admin(club_id));
CREATE POLICY members_delete ON public.club_members FOR DELETE TO authenticated USING(public.racqr_admin(club_id));
CREATE FUNCTION public.racqr_new_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO profiles(id,name,email) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'name',NEW.raw_user_meta_data->>'full_name',''),coalesce(NEW.email,'')); RETURN NEW; END $$;
CREATE TRIGGER racqr_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.racqr_new_profile();
CREATE FUNCTION public.racqr_club_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO club_members(club_id,user_id,role,approved) VALUES(NEW.id,NEW.owner_id,'admin',true); RETURN NEW; END $$;
CREATE TRIGGER racqr_club_created AFTER INSERT ON public.clubs FOR EACH ROW EXECUTE FUNCTION public.racqr_club_owner();
CREATE FUNCTION public.racqr_join_club(club_slug text,requested_role text DEFAULT 'customer') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT id INTO c FROM clubs WHERE slug=club_slug; IF c IS NULL THEN RAISE EXCEPTION 'Club not found'; END IF; INSERT INTO club_members(club_id,user_id,role,approved) VALUES(c,auth.uid(),CASE WHEN requested_role='stringer' THEN 'stringer' ELSE 'customer' END,false) ON CONFLICT(club_id,user_id) DO NOTHING; RETURN c; END $$;
REVOKE ALL ON FUNCTION public.racqr_join_club(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.racqr_join_club(text,text) TO authenticated;
CREATE TABLE public.jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), club_id uuid NOT NULL REFERENCES public.clubs(id) ON DELETE CASCADE, job_number text NOT NULL DEFAULT '', customer_id uuid REFERENCES public.profiles(id), customer_name text NOT NULL, customer_phone text DEFAULT '', customer_email text DEFAULT '', racket text NOT NULL, head_size numeric DEFAULT 98, pattern text DEFAULT '16x19', mains_string text NOT NULL, crosses_string text DEFAULT '', unit text NOT NULL DEFAULT 'lb' CHECK(unit IN ('lb','kg')), mains_tension numeric NOT NULL CHECK(mains_tension>0), crosses_tension numeric NOT NULL CHECK(crosses_tension>0), pre_stretch text DEFAULT '0%', knots integer DEFAULT 4 CHECK(knots IN (2,4)), status text NOT NULL DEFAULT 'received' CHECK(status IN ('received','in_progress','ready','collected')), payment_status text NOT NULL DEFAULT 'u' CHECK(payment_status IN ('u','d','p')), amount numeric NOT NULL DEFAULT 0 CHECK(amount>=0), currency text DEFAULT '$', payment_method text DEFAULT '', date_in date NOT NULL DEFAULT CURRENT_DATE, ready_by date, notes text DEFAULT '', created_at timestamptz DEFAULT now(), UNIQUE(club_id,job_number));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.jobs TO authenticated; GRANT ALL ON public.jobs TO service_role;
ALTER TABLE public.jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY jobs_read ON public.jobs FOR SELECT TO authenticated USING(public.racqr_staff(club_id) OR (public.racqr_member(club_id) AND customer_id=auth.uid()));
CREATE POLICY jobs_create ON public.jobs FOR INSERT TO authenticated WITH CHECK(public.racqr_staff(club_id) OR (public.racqr_member(club_id) AND customer_id=auth.uid() AND status='received' AND payment_status='u' AND amount=0 AND coalesce(payment_method,'')=''));
CREATE POLICY jobs_update ON public.jobs FOR UPDATE TO authenticated USING(public.racqr_staff(club_id)) WITH CHECK(public.racqr_staff(club_id));
CREATE POLICY jobs_delete ON public.jobs FOR DELETE TO authenticated USING(public.racqr_staff(club_id));
CREATE SEQUENCE public.racqr_job_seq;
CREATE FUNCTION public.racqr_job_defaults() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p profiles; BEGIN IF TG_OP='INSERT' THEN IF NEW.job_number='' THEN SELECT upper(substr(regexp_replace(slug,'[^a-zA-Z]','','g'),1,5))||'-'||lpad(nextval('racqr_job_seq')::text,4,'0') INTO NEW.job_number FROM clubs WHERE id=NEW.club_id; END IF; IF NOT racqr_staff(NEW.club_id) THEN SELECT * INTO p FROM profiles WHERE id=auth.uid(); NEW.customer_id=auth.uid(); NEW.customer_name=p.name; NEW.customer_phone=p.phone; NEW.customer_email=p.email; NEW.status='received'; NEW.payment_status='u'; NEW.amount=0; NEW.payment_method=''; END IF; ELSIF NEW.club_id IS DISTINCT FROM OLD.club_id THEN RAISE EXCEPTION 'Cannot move jobs between clubs'; END IF; RETURN NEW; END $$;
CREATE TRIGGER racqr_validate_job BEFORE INSERT OR UPDATE ON public.jobs FOR EACH ROW EXECUTE FUNCTION public.racqr_job_defaults();
CREATE INDEX racqr_jobs_club ON public.jobs(club_id,created_at DESC);
CREATE POLICY photo_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='profile-photos' AND public.racqr_can_view_profile((storage.foldername(name))[1]::uuid));
CREATE POLICY photo_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='profile-photos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY photo_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='profile-photos' AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id='profile-photos' AND (storage.foldername(name))[1]=auth.uid()::text);